grids.grid:
&DefaultButton;
declare @strKey nvarchar(128) exec ISWIFTStoreTableLoading '@@table', '@@fieldKey', '@@fields', @@fieldOrder, '', '', 'left join sysunit b on a.unit_id = b.unit_id left join dmnhomvb d on a.ma_nvb = d.ma_nvb and d.ma_loai = ''VB'' left join dmtgluuvb e on a.ma_tg = e.ma_tg ', 'b.ma_unit, d.ten_nvb, e.ten_tg', '@@key', @strKey, @@filterKey, '', @pageIndex, 50, @@admin, @@userId --@@columnFilterKey
declare @strKey nvarchar(3000) set @strKey = 'ngay_ct between ''' + convert(char(8), @ngay_ct1, 112) + ''' and ''' + convert(char(8), @ngay_ct2, 112) + ''' and ' + @strFinding exec ISWIFTStoreTableLoading '@@table', '@@fieldKey', '@@fields', @@fieldOrder, '', '', ' left join sysunit b on a.unit_id = b.unit_id left join dmnhomvb d on a.ma_nvb = d.ma_nvb and d.ma_loai = ''VB'' left join dmtgluuvb e on a.ma_tg = e.ma_tg ', 'b.ma_unit, d.ten_nvb, e.ten_tg', '@@key', @strKey, @@filterKey, '', @pageIndex, 50, @@admin, @@userId --@@columnFilterKey

js.text:

function grid$dmvb_ck(f){
  this.constructor(f);
}
grid$dmvb_ck.prototype = new DirEvent();
grid$dmvb_ck.prototype.afterInit = function(){
  var p = this._dir;
}

css.text:

.tree-form{
	width: 250px;
}
.ic-view-dept{
  background-position: 0px 0px;
}
.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 960px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
